<?php
require_once __DIR__.'/../includes/auth.php';auth_require();require_once __DIR__.'/../includes/listing.php';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 if(($_POST['action']??'')==='approve_closing'){
  domain_require('closings.approve');$q=$pdo->prepare("UPDATE daily_closings SET status='approved',approved_by=? WHERE id=? AND shop_id=? AND status='submitted' AND created_by<>?");$q->execute([auth_user()['id'],(int)($_POST['closing_id']??0),shop_id(),auth_user()['id']]);if($q->rowCount()!==1)throw new InvalidArgumentException('Closing not found, already approved, or self-approval is not allowed.');domain_audit('closing_approved','closing',$_POST['closing_id']);
 }else{
  domain_require('closings.create');$date=$_POST['closing_date']??'';$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date||$date>date('Y-m-d'))throw new InvalidArgumentException('Invalid date.');
  $ctx=currency_context($_POST);$q=$pdo->prepare("SELECT id FROM fund_accounts WHERE shop_id=? AND currency_code=? AND kind='cash' AND status='active'");$q->execute([shop_id(),$ctx['code']]);$cashAccounts=$q->fetchAll(PDO::FETCH_COLUMN);if(!$cashAccounts)throw new InvalidArgumentException('Create a cash account before closing the day.');$expected='0.00';foreach($cashAccounts as $account)$expected=dec_add($expected,funds_balance((int)$account,$date));$actual=dec_round($_POST['actual']??'');if(dec_units($actual)<0||dec_units($expected)<0)throw new InvalidArgumentException('Negative cash count.');$notes=trim((string)($_POST['notes']??''));if(mb_strlen($notes)<3||mb_strlen($notes)>1000)throw new InvalidArgumentException('Explain the expected balance and any difference.');
  $pdo->prepare('INSERT INTO daily_closings (shop_id,currency_code,closing_date,expected_amount,actual_amount,difference_amount,notes,created_by) VALUES (?,?,?,?,?,?,?,?)')->execute([shop_id(),$ctx['code'],$date,$expected,$actual,dec_sub($actual,$expected),$notes,auth_user()['id']]);domain_audit('closing_submitted','closing',$pdo->lastInsertId(),['expected'=>$expected,'actual'=>$actual,'currency'=>$ctx['code']]);
 }redirect(BASE_URL.'modules/closing.php');
}catch(Throwable $e){http_response_code(422);$error=$e instanceof PDOException?__t('A closing already exists for this date and currency, or saving failed.','برای این تاریخ و ارز قبلاً حساب روز ثبت شده، یا ذخیره ناکام شد.','د دې نېټې حساب مخکې ثبت شوی.'): public_error($e);}
$sorts=['newest'=>['id DESC','Newest first','تازه‌ترین اول'],'oldest'=>['id ASC','Oldest first','قدیمی‌ترین اول']];[$list,$history]=listing_query($pdo,'SELECT * FROM daily_closings WHERE shop_id=?',[shop_id()],$sorts);$pageTitle=__t('Daily cash reconciliation','تطبیق حساب روز صندوق','د ورځې د نغدو حساب');require __DIR__.'/../includes/header.php';?>
<section class="card modern-form"><h2><?= sanitize($pageTitle) ?></h2><p><?= __t('The expected balance is calculated from all recorded cash accounts in this branch and currency through the selected date. Count actual cash; bank accounts are excluded. Approval requires another authorized person.','ماندهٔ مورد انتظار از تمام حساب‌های نقدی ثبت‌شدهٔ این شعبه و ارز تا تاریخ انتخابی محاسبه می‌شود. پول واقعی را بشمارید؛ حساب بانکی شامل شمارش نقد نیست. شخص مجاز دیگری باید تأیید کند.','تمه شوې او واقعي نغدې ولیکئ؛ بل مجاز کس یې تاییدوي.') ?></p><?php if($error):?><p role="alert"><?= sanitize($error) ?></p><?php endif ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="create_closing"><div class="form-grid"><label><?= __t('Date','تاریخ','نېټه') ?><input class="form-control" type="date" name="closing_date" value="<?= date('Y-m-d') ?>" required></label><label><?= __t('Currency','ارز','اسعار') ?><?= currency_select('currency_code') ?></label><label><?= __t('Actual cash','پول واقعی','واقعي نغدې') ?><input class="form-control" type="number" min="0" step="0.01" name="actual" required></label></div><label><?= __t('Balance source & explanation','مرجع رقم و توضیحات','سرچینه او سپیناوی') ?><textarea class="form-control" name="notes" minlength="3" maxlength="1000" required></textarea></label><button class="btn btn-primary"><?= __t('Submit closing','ثبت حساب روز','د ورځې حساب ثبت') ?></button></form></section>
<section class="card modern-form table-responsive"><table class="table"><thead><tr><?php foreach([__t('Date','تاریخ','نېټه'),__t('Currency','ارز','اسعار'),__t('Expected','مورد انتظار','تمه'),__t('Actual','واقعی','واقعي'),__t('Difference','اختلاف','توپیر'),__t('Status','وضعیت','حالت')] as $h):?><th><?= $h ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($history as $r):?><tr><td><?= sanitize($r['closing_date']) ?></td><td><?= sanitize($r['currency_code']) ?></td><td><?= sanitize($r['expected_amount']) ?></td><td><?= sanitize($r['actual_amount']) ?></td><td><?= sanitize($r['difference_amount']) ?></td><td><?= $r['status']==='approved'?__t('Approved','تأییدشده','تایید شوی'):__t('Awaiting approval','در انتظار تأیید','تایید ته منتظر') ?><?php if($r['status']==='submitted'&&(int)$r['created_by']!==(int)auth_user()['id']&&domain_can('closings.approve')):?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="approve_closing"><input type="hidden" name="closing_id" value="<?= (int)$r['id'] ?>"><button class="btn btn-primary"><?= __t('Approve','تأیید','تایید') ?></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></section>
<?php listing_controls_form($list);listing_footer($list);require __DIR__.'/../includes/footer.php'; ?>
